+/*
+ * The receive completion interrupt is delivered on whichever hart happens to
+ * be running, in whatever address space happens to be installed -- and with
+ * SUM cleared, so the handler cannot touch user memory at all.  It therefore
+ * drops the frames into this kernel staging area, and do_net_recv() hands
+ * them over once the caller has been scheduled again.
+ */
+static EthernetFrame recv_stage[RXBD_CNT];
+static size_t recv_stage_len[RXBD_CNT];
+
 long do_net_recv(uintptr_t addr, size_t length, int num_packet, size_t* frLength)
 {
-    /* TODO: implement */
-    return -1;
+    // receive packet by calling network driver's function
+    // wait until you receive enough packets(`num_packet`).
+    if(num_packet <= 0 || num_packet > RXBD_CNT){
+        return -1;
+    }
+
+    /* interrupts must stay off until we are queued on net_recv_queue,
+     * otherwise the handler would wake up an empty queue */
+    disable_preempt();
+
+    recv_transaction = 1;
+    enable_sum();
+    for(int i = 0; i < num_packet; i++){
+        memset(&rx_buffers[i], 0, sizeof(EthernetFrame));
+        rx_len[i] = 0;
+    }
+    EmacPsRecv(&EmacPsInstance, 0, num_packet);
+
+    if(net_poll_mode == 0){
+        /* poll mode: spin until every descriptor has been handed back */
+        EmacPsWaitRecv(&EmacPsInstance, num_packet, rx_len);
+        rx_curr = addr;
+        rx_tail = 0;
+        for(int i = 0; i < num_packet; i++){
+            memcpy((uint8_t*)rx_curr, (uint8_t*)&rx_buffers[i], rx_len[i]);
+            *(frLength + i) = rx_len[i];
+            rx_curr += rx_len[i];
+            rx_tail += rx_len[i];
+        }
+        recv_transaction = 0;
+        disable_sum();
+        enable_preempt();
+        return rx_tail;
+    }
+    else if(net_poll_mode == 1){
+        /* interrupt mode: sleep until XEmacPsRecvHandler() has staged the
+         * frames for us, then copy them out in our own address space */
+        _addr = (uintptr_t)recv_stage;
+        _num_packet = num_packet;
+        _frLength = recv_stage_len;
+        do_block(&current_running[cpu_id]->list, &net_recv_queue);
+        disable_sum();
+        scheduler();
+        enable_preempt();
+
+        enable_sum();
+        rx_curr = addr;
+        rx_tail = 0;
+        for(int i = 0; i < num_packet; i++){
+            memcpy((uint8_t*)rx_curr, (uint8_t*)recv_stage + rx_tail, recv_stage_len[i]);
+            *(frLength + i) = recv_stage_len[i];
+            rx_curr += recv_stage_len[i];
+            rx_tail += recv_stage_len[i];
+        }
+        disable_sum();
+        return rx_tail;
+    }
+    else{
+        recv_transaction = 0;
+        disable_sum();
+        enable_preempt();
+        return -1;
+    }
 }

