    59	
    60	static inline void plic_toggle(struct plic_handler *handler,
    61					int hwirq, int enable)
    62	{
    63		u32 *reg = handler->enable_base + (hwirq / 32) * sizeof(u32);
    64		u32 hwirq_mask = 1 << (hwirq % 32);
    65	
    66		if (enable)
    67			writel(readl(reg) | hwirq_mask, reg);
    68		else
    69			writel(readl(reg) & ~hwirq_mask, reg);
    70	}
    71	
    72	static void plic_irq_unmask(int hwirq)
    73	{
    74		int enable = 1;
    75		writel(enable, plic_regs + PRIORITY_BASE + hwirq * PRIORITY_PER_ID);
    76	    struct plic_handler *handler = &plic_handlers;
    77	
    78	    if (handler->present) plic_toggle(handler, hwirq, enable);
    79	}
