   116	/*
   117	 * Handling an interrupt is a two-step process: first you claim the interrupt
   118	 * by reading the claim register, then you complete the interrupt by writing
   119	 * that source ID back to the same claim register.  This automatically enables
   120	 * and disables the interrupt, so there's nothing else to do.
   121	 */
   122	void plic_handle_irq(regs_context_t *regs)
   123	{
   124		struct plic_handler *handler = &plic_handlers;
   125		void *claim = handler->hart_base + CONTEXT_CLAIM;
   126		int hwirq;
   127	
   128		csr_clear(sie, SIE_SEIE);
   129		while ((hwirq = readl(claim))) {
   130				handle_irq(regs, hwirq);
   131		}
   132		csr_set(sie, SIE_SEIE);
   133	}
